package org.springframework.samples.petclinic.rest.validation;

/**
 * Raised when a new owner is submitted whose last name and address already belong to another owner
 * (compared case-insensitively with collapsed whitespace), so the client can be told the record
 * conflicts with an existing household. The client may override this by opting in with
 * {@code sharesHousehold}.
 */
public class DuplicateHouseholdException extends RuntimeException {

    private final String lastName;

    private final String address;

    public DuplicateHouseholdException(String lastName, String address) {
        super("An owner with the same last name and address already exists: " + lastName + ", " + address);
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return this.lastName;
    }

    public String getAddress() {
        return this.address;
    }
}

